<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\CommitteeMember; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class CommitteeMemberController extends Controller { public function index(){return CommitteeMember::orderBy('created_at')->get();} public function store(Request $r){$d=$r->validate(['name'=>'required|max:40','role'=>'required|max:40','mobile'=>'nullable|max:20','photo'=>'nullable|image|max:2048']); if($r->hasFile('photo')) $d['photo']=$r->file('photo')->store('committee-members','public'); return CommitteeMember::create($d);} public function show(CommitteeMember $committee_member){return $committee_member;} public function update(Request $r,CommitteeMember $committee_member){$d=$r->validate(['name'=>'sometimes|max:40','role'=>'sometimes|max:40','mobile'=>'nullable|max:20','photo'=>'nullable|image|max:2048']); if($r->hasFile('photo')){ if($committee_member->photo) Storage::disk('public')->delete($committee_member->photo); $d['photo']=$r->file('photo')->store('committee-members','public'); } $committee_member->update($d); return $committee_member;} public function destroy(CommitteeMember $committee_member){ if($committee_member->photo) Storage::disk('public')->delete($committee_member->photo); $committee_member->delete(); return response()->noContent();} }
